package com.clavis.reader;
/** Pure text operations shared by the local speech player and its checks. */
final class NarrationText {
 static String clean(String text){return text.replace("\u00ad","").replaceAll("(?<=\\p{L})-\\r?\\n(?=\\p{Ll})","").replaceAll("[\\t\\x0B\\f ]+"," ").replaceAll(" *\\r?\\n *","\n").replaceAll("\n{3,}","\n\n").replaceAll("(?<!\n)\n(?!\n)"," ").trim();}
 static String spoken(String text){String value=java.text.Normalizer.normalize(clean(text),java.text.Normalizer.Form.NFKC).replace('\u00a0',' ');String[][] titles={{"Mrs","Missus"},{"Mr","Mister"},{"Dr","Doctor"},{"Prof","Professor"},{"Ms","Miz"}};for(String[] title:titles)value=value.replaceAll("(?i)\\b"+title[0]+"\\.(?=\\s)",title[1]);java.util.regex.Matcher chapters=java.util.regex.Pattern.compile("\\b((?i:chapter|book|part))\\s+([IVXLCDM]+|\\d+)\\b(?!\\.\\d)").matcher(value);StringBuffer spoken=new StringBuffer();while(chapters.find()){String number=chapters.group(2);int n=-1;try{n=number.matches("\\d+")?Integer.parseInt(number):roman(number);}catch(Exception ignored){}String label=chapters.group(1);String replacement=n>=0&&n<4000?label.substring(0,1).toUpperCase(java.util.Locale.US)+label.substring(1).toLowerCase(java.util.Locale.US)+" "+numberWords(n):chapters.group();chapters.appendReplacement(spoken,java.util.regex.Matcher.quoteReplacement(replacement));}chapters.appendTail(spoken);return spoken.toString();}
 static int roman(String value){if(value.isEmpty()||!value.matches("M{0,3}(CM|CD|D?C{0,3})(XC|XL|L?X{0,3})(IX|IV|V?I{0,3})"))return -1;int total=0,previous=0;for(int n=value.length()-1;n>=0;n--){int current=new int[]{1,5,10,50,100,500,1000}["IVXLCDM".indexOf(value.charAt(n))];total+=current<previous?-current:current;previous=current;}return total;}
 static String numberWords(int n){String[] small={"zero","one","two","three","four","five","six","seven","eight","nine","ten","eleven","twelve","thirteen","fourteen","fifteen","sixteen","seventeen","eighteen","nineteen"},tens={"","","twenty","thirty","forty","fifty","sixty","seventy","eighty","ninety"};if(n<20)return small[n];if(n<100)return tens[n/10]+(n%10==0?"":" "+small[n%10]);if(n<1000)return small[n/100]+" hundred"+(n%100==0?"":" "+numberWords(n%100));return small[n/1000]+" thousand"+(n%1000==0?"":" "+numberWords(n%1000));}
 static int end(String text,int start){return end(text,start,600);}
 static int end(String text,int start,int span){int limit=Math.min(text.length(),start+span);if(limit==text.length())return limit;int best=-1;for(int n=start+1;n<limit;n++){char c=text.charAt(n);if(c=='.'||c=='!'||c=='?'||c=='\n'){int after=n+1;while(after<limit&&"\"'”’)]".indexOf(text.charAt(after))>=0)after++;if(after<text.length()&&Character.isWhitespace(text.charAt(after))&&!abbreviation(text,n))best=after;}}if(best>start+Math.min(80,span/3))return best;int extended=Math.min(text.length(),limit+300);for(int n=limit;n<extended;n++){char c=text.charAt(n);if(c=='.'||c=='!'||c=='?'){int after=n+1;while(after<extended&&"\"'”’)]".indexOf(text.charAt(after))>=0)after++;if((after==text.length()||Character.isWhitespace(text.charAt(after)))&&!abbreviation(text,n))return after;}}int space=text.lastIndexOf(' ',limit);if(space>start)return space+1;if(Character.isLowSurrogate(text.charAt(limit)))limit--;return limit;}
 static boolean abbreviation(String text,int point){if(text.charAt(point)!='.')return false;if(point>0&&point+1<text.length()&&Character.isDigit(text.charAt(point-1))&&Character.isDigit(text.charAt(point+1)))return true;int start=point;while(start>0&&Character.isLetter(text.charAt(start-1)))start--;String word=text.substring(start,point);return word.matches("(?i)Mr|Mrs|Ms|Dr|Prof|Sr|Jr|St|vs|etc")||word.length()==1;}
 static int[] activeRange(String text,int first,int last,int position){int begin=first;for(int n=first;n<last;n++){char c=text.charAt(n);int after=-1;if(c=='\n'&&n+1<last&&text.charAt(n+1)=='\n')after=n+2;else if((c=='.'||c=='!'||c=='?')&&!abbreviation(text,n)){int end=n+1;while(end<last&&"\"'”’)]".indexOf(text.charAt(end))>=0)end++;if(end==last||Character.isWhitespace(text.charAt(end)))after=end;}if(after>begin){if(position<after)return new int[]{begin,Math.min(last,after)};begin=after;while(begin<last&&Character.isWhitespace(text.charAt(begin)))begin++;n=begin-1;}}return new int[]{Math.min(begin,last),last};}
 static final java.util.regex.Pattern WORD=java.util.regex.Pattern.compile("[\\p{L}\\p{N}][\\p{L}\\p{M}\\p{N}]*(?:['’\\-][\\p{L}\\p{M}\\p{N}]+)*");
 static int skipWords(String text,int position,int count){int at=Math.max(0,Math.min(text.length(),position));if(count==0)return at;while(at<text.length()&&Character.isWhitespace(text.charAt(at)))at++;java.util.regex.Matcher words=WORD.matcher(text);int anchor=at;if(at<text.length()){words.region(wordStart(text,at),text.length());if(words.find())anchor=words.start();else anchor=text.length();}if(count>0){words.region(anchor,text.length());for(int n=0;n<=count;n++)if(!words.find())return text.length();return words.start();}int size=-count,found=0;int[] previous=new int[size];words.region(0,anchor);while(words.find()){previous[found%size]=words.start();found++;}return found==0?0:previous[found<size?0:found%size];}
 static int wordStart(String text,int position){int p=Math.max(0,Math.min(text.length(),position));if(p<text.length()&&p>0&&Character.isLowSurrogate(text.charAt(p)))p--;while(p>0&&p<text.length()&&!Character.isWhitespace(text.charAt(p-1)))p--;return p;}
}
